-- NCAAF power rating sets (one row per source + season, ratings as JSONB)
-- Run this whole file once in the Supabase SQL editor.
-- Pattern matches eckel_snapshots: no RLS, anon key has full access.

create table if not exists power_rating_sets (
  id bigint generated always as identity primary key,
  sport text not null default 'ncaaf',
  source text not null,
  source_label text not null,
  season int not null,
  as_of date,
  ratings jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (sport, source, season)
);

